use aap::caps::http_client;

struct Node;

/// Convenience pre-filter mirroring the grant's allowlist. The host still
/// enforces the allowlist; this only avoids a trap on URLs the host would refuse.
const PERMITTED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host from an `https://` URL. Returns `None` for anything with
/// userinfo, a port, whitespace, control characters, or an empty authority.
fn host_of(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("https://")?;
    let end = rest
        .find(|c: char| matches!(c, '/' | '?' | '#'))
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty()
        || authority
            .chars()
            .any(|c| c == '@' || c == ':' || c == '\\' || c <= ' ')
    {
        return None;
    }
    Some(authority)
}

fn is_permitted(url: &str) -> bool {
    match host_of(url) {
        Some(host) => PERMITTED_HOSTS
            .iter()
            .any(|allowed| allowed.eq_ignore_ascii_case(host)),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !is_permitted(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url is not on a permitted host".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
